import xml.etree.ElementTree as ET

# Parse right_hand.xml (the real content)
tree = ET.parse("/Users/wangyifan/Projects/auto_adapter2.0/AA1/assets/mjcf/leap_hand/right_hand.xml")
root = tree.getroot()

# ── 1. Collect default class ranges ──────────────────────────────────────────
defaults = {}
for cls in root.iter("default"):
    cname = cls.get("class")
    if cname is None:
        continue
    jnt = cls.find("joint")
    pos = cls.find("position")
    axis = [0, 0, -1]  # all joints share this default axis
    if jnt is not None:
        rng = jnt.get("range")
        ax  = jnt.get("axis")
        if ax:
            axis = [float(v) for v in ax.split()]
        if rng:
            lo, hi = [float(v) for v in rng.split()]
            defaults[cname] = {"axis": axis, "ctrlrange": [lo, hi]}
    if pos is not None and cname not in defaults:
        rng = pos.get("ctrlrange")
        if rng:
            lo, hi = [float(v) for v in rng.split()]
            defaults[cname] = {"axis": axis, "ctrlrange": [lo, hi]}

print("Defaults by class:")
for k, v in defaults.items():
    print(f"  {k}: {v}")
